const coreCourses = [["ai","What is AI?","Beginner",["AI problem framing and intelligent tasks","A short history of artificial intelligence","AI, ML, deep learning and generative AI","Rule-based and data-driven systems","Data, features, labels and representations","Search, planning and reasoning","Perception: vision, speech and sensors","Language systems and conversational AI","Recommendation, prediction and automation","How AI systems are evaluated","Bias, privacy, safety and human oversight","Capstone: map an AI solution to a real problem"]],["ml","Machine Learning","Beginner",["What machine learning means","Classification, regression and ranking","Supervised learning and labelled data","Unsupervised learning and clustering","Reinforcement learning foundations","Features, labels and data quality","Train, validation and test splits","Linear models and decision trees","Loss functions and optimisation","Metrics: precision, recall, F1 and ROC","Overfitting, underfitting and leakage","Project: build a prediction workflow"]],["dl","Deep Learning","Beginner",["Artificial neurons and perceptrons","Weights, biases and weighted sums","Activation functions and non-linearity","Layers and network architectures","Forward propagation","Loss functions for learning","Gradient descent and learning rates","Backpropagation intuition","Epochs, batches and optimisers","CNNs, sequence models and transformers","Regularisation and overfitting","Project: design a neural network"]],["genai","Generative AI","Beginner",["What makes AI generative","Predictive AI versus generative AI","Training data and learned representations","Transformer and diffusion model families","Text generation workflow","Image generation workflow","Audio, speech and video generation","Multimodal inputs and outputs","Prompting and inference settings","Hallucinations and verification","Copyright, privacy, bias and misuse","Project: design a reviewed generative workflow"]],["llm","What is an LLM?","Beginner",["What a large language model is","Text tokenisation and token IDs","Embeddings and positional information","Transformer architecture overview","Attention and contextual representations","Next-token prediction","Pretraining and instruction tuning","Context windows and long conversations","Sampling: temperature and top-p","Hallucinations and factual reliability","Model limits, privacy and safety","Project: test an LLM"]],["prompt","Prompt Engineering","Beginner",["Prompting as clear task specification","Task, context, audience and output format","Role and perspective instructions","Examples and few-shot prompting","Constraints and acceptance criteria","Structured outputs and JSON requests","Grounding answers in supplied sources","Prompt decomposition and multi-step tasks","Iterative refinement and error analysis","Prompt injection and untrusted input","Reusable prompt templates and evaluation","Project: build a tested prompt library"]],["python-basics","Python Essentials for AI","Beginner",["Python setup, notebooks and execution","Variables, values and core data types","Strings, formatting and input","Lists, tuples, sets and dictionaries","Conditions and boolean logic","For loops, while loops and iteration","Functions, parameters and return values","Modules, packages and environments","Exceptions, debugging and testing","Files, CSV and JSON basics","Readable, reusable Python","Project: build a data-inspection program"]],["math-for-ai","Mathematics for AI","Beginner",["Numbers, notation and algebra refresh","Scalars and vectors","Vector addition, magnitude and dot product","Matrices and matrix multiplication","Functions and graphs","Slopes, derivatives and rates of change","Partial derivatives and gradients","Gradient descent intuition","Probability and conditional probability","Distributions, expectation and variance","Distance, similarity and optimisation","Project: calculate a model update"]],["data-with-python","Working with Data: NumPy & Pandas","Beginner",["Arrays and NumPy mental model","Array creation, shape and data types","Indexing, slicing and vectorised operations","Broadcasting and aggregation","Pandas Series and DataFrames","Read and inspect CSV data","Select, filter and sort rows","Group, aggregate and join tables","Missing values and duplicates","Dates, strings and data types","Reproducible preprocessing and leakage","Project: clean and analyse a dataset"]],["statistics-visualization","Statistics & Data Visualisation","Beginner",["Populations, samples and data types","Mean, median, mode and quantiles","Range, variance and standard deviation","Distributions, skew and outliers","Probability and sampling variability","Confidence intervals and uncertainty","Hypothesis testing and p-values","Correlation versus causation","Bar, line, histogram and scatter charts","Chart design and misleading visuals","Exploratory data analysis workflow","Project: present a data story"]],["embeddings","Embeddings and Vector Mathematics","Intermediate",["Why represent content as vectors","Embedding models and vector dimensions","Token, sentence and document embeddings","Vector norms and normalisation","Dot product and cosine similarity","Euclidean and other distance measures","Semantic neighbourhoods and clustering","Query and document embedding alignment","Multilingual and multimodal embeddings","Embedding drift and version changes","Evaluate similarity with labelled examples","Project: semantic similarity experiment"]],["vectordb","Vector Databases","Intermediate",["Why vector search is useful","Records, vectors and metadata schema","Similarity search and top-k","Exact versus approximate nearest neighbours","Index concepts and recall-latency trade-offs","Metadata filtering and tenant isolation","Upserts, deletes and index refresh","Hybrid search and sparse signals","Scaling, sharding and replication","Access control, backup and observability","Benchmarking vector retrieval","Project: index a document collection"]],["semantic-search","Semantic Search","Intermediate",["Keyword search and its limits","Semantic search concepts","Query and document encoding","Candidate generation and top-k retrieval","Cosine similarity and relevance","Hybrid lexical and vector retrieval","Metadata filters and facets","Reranking and learning-to-rank","Query rewriting and expansion","Search evaluation: recall, precision and NDCG","Latency, freshness and analytics","Project: evaluate a domain search engine"]],["chunking","Document Chunking","Intermediate",["Why documents are chunked","Parsing PDFs, HTML and office files","Structure-aware splitting","Fixed-size and token-based chunking","Recursive and semantic chunking","Overlap and context windows","Tables, code and structured content","Metadata, page numbers and provenance","Parent-child and hierarchical retrieval","Chunk quality and retrieval evaluation","Versioning, deduplication and re-indexing","Project: create a traceable document index"]],["rag","RAG: Retrieval-Augmented Generation","Intermediate",["What RAG is and why it is needed","LLM knowledge limits and freshness","RAG architecture and request lifecycle","Document ingestion and parsing","Text cleaning and preprocessing","Chunking strategies and overlap","Embeddings and vector representations","Vector databases and indexing","Retrieval, ranking and reranking","Grounded prompt construction","Build a document-question-answering assistant","Evaluation, debugging and production"]],["ai-agents","AI Agents & Tool Calling","Intermediate",["Agents, workflows and ordinary chat","Agent loop: observe, decide and act","Tool schemas and structured arguments","Tool execution and result handling","Planning and task decomposition","State, memory and context management","Multi-agent patterns and delegation","Human approval and permission boundaries","Retries, timeouts and idempotency","Tracing, testing and agent evaluation","Security risks and prompt injection","Project: build a bounded tool-using assistant"]],["finetuning","Fine-Tuning and Model Customisation","Advanced",["Model adaptation strategy landscape","Prompting, RAG and fine-tuning comparison","When fine-tuning is justified","Dataset design and curation","Instruction examples and formatting","Train, validation and test design","Supervised fine-tuning workflow","Parameter-efficient methods and LoRA","Hyperparameters and training monitoring","Evaluate capability, regressions and safety","Model versioning and deployment","Project: adaptation decision and evaluation plan"]]];
const context = {"ai":"AI systems","ml":"machine learning models","dl":"neural networks","genai":"generative models","llm":"language models","prompt":"prompt workflows","python-basics":"Python programs","math-for-ai":"mathematical methods","data-with-python":"data analysis pipelines","statistics-visualization":"statistical analysis","embeddings":"embedding pipelines","vectordb":"vector indexes","semantic-search":"search systems","chunking":"document retrieval","rag":"RAG assistants","ai-agents":"tool-using agents","finetuning":"adapted foundation models"};
const levels = {Beginner:"Build conceptual foundations and apply them to a guided example.",Intermediate:"Implement the workflow, evaluate behaviour and explain engineering trade-offs.",Advanced:"Make defensible adaptation decisions and validate them with evidence."};

const teaching = {
 ai:{focus:"AI systems combine data, a task representation, a model or rule engine, an output policy and a feedback loop. Choose the simplest system that meets the user need.",example:"A returns desk can route clear policy cases with rules, use a classifier to prioritise ambiguous cases and send exceptions to a human.",ideas:["Separate the user problem from the proposed technique.","Distinguish prediction, classification, generation, retrieval and planning.","Map data, model, interface, feedback and human review.","Compare AI with a deterministic baseline.","Define acceptable errors and escalation paths."]},
 ml:{focus:"A supervised dataset contains observations, features and a target label. The algorithm learns parameters by minimising a loss on training examples; validation supports model selection and a final untouched test set estimates generalisation.",example:"For loan-default prediction, each row is an applicant, debt-to-income and repayment history are possible features, and default within a defined time window is the label. Exclude information only known after the decision and consider a time-based split.",ideas:["A feature is available at prediction time; a label is the outcome to predict.","Classification predicts classes; regression predicts numeric values.","Fit preprocessing on training data only to prevent leakage.","Use validation for model selection and preserve a final test set.","Choose precision and recall based on false-positive and false-negative costs."]},
 dl:{focus:"A neuron computes a weighted sum plus bias and applies an activation. Layers compose transformations; training uses a forward pass, a loss, backpropagated gradients and an optimiser to update parameters.",example:"A digit classifier receives pixel tensors, learns local patterns with convolutional layers and outputs scores for digits 0–9. Inspect a confusion matrix and test on writers not represented in training.",ideas:["Weights and biases control each neuron's transformation.","Non-linear activations let stacked layers model complex functions.","Backpropagation applies the chain rule to calculate gradients.","Learning rate and batch size influence optimisation.","Training and validation curves expose overfitting."]},
 genai:{focus:"Generative models produce candidate content conditioned on prompts and context. Autoregressive systems predict sequence elements; diffusion systems iteratively denoise. Output quality requires verification and controls.",example:"Generate product descriptions from an approved catalogue, validate every factual attribute against source data and route uncertain claims to a reviewer.",ideas:["Generation creates candidate content, not verified facts.","Autoregressive and diffusion models use different generation processes.","Prompts condition output but do not guarantee compliance.","Sampling settings affect diversity and repeatability.","Validate factual claims, rights, safety and provenance."]},
 llm:{focus:"An LLM tokenises text, maps token IDs to vectors, processes them through transformer blocks and generates by repeatedly selecting a next token. Attention mixes contextual information; decoding controls token selection.",example:"Give a support LLM approved policy passages and ask it to answer with citations. Test unsupported questions and verify that it abstains rather than inventing policy.",ideas:["Tokenisation converts text into token IDs.","Embeddings represent tokens as vectors; positional information preserves order.","Self-attention mixes context across token positions.","Next-token prediction is the core generation objective.","Context limits do not guarantee reliable use of every detail."]},
 prompt:{focus:"Treat a prompt as an interface contract: specify task, trusted context, constraints, output schema and uncertainty behaviour. Evaluate prompt versions on the same representative and adversarial test cases.",example:"Extract invoice fields into JSON, require null for absent values, prohibit guessing and validate the response against a schema before accepting it.",ideas:["Specify task, audience and desired output.","Separate trusted instructions from untrusted input.","Use examples to clarify edge cases.","Define constraints and refusal conditions.","Test prompt changes against a fixed evaluation set."]},
 "python-basics":{focus:"Python programs combine objects and data types, control flow, functions, modules and exception handling. Reproducible AI work requires code that runs from a clean environment and can be tested independently.",example:"Read a CSV of support tickets, validate required columns, count missing descriptions and write a JSON summary. Put parsing and validation in functions and test them on a small fixture.",ideas:["Choose types that match the data being represented.","Use lists for ordered collections and dictionaries for keyed records.","Use conditions and loops for explicit control flow.","Write functions with clear inputs and outputs.","Handle expected exceptions and test from a clean runtime."]},
 "math-for-ai":{focus:"Linear algebra represents data and transformations; calculus describes how parameters affect a loss; probability describes uncertainty. Gradients collect partial derivatives and guide optimisation.",example:"For prediction wx+b, calculate squared error on two observations, derive gradients for w and b, perform one gradient-descent update and verify whether loss decreases.",ideas:["Track vector and matrix shapes before operations.","Use dot products for weighted sums and similarity.","Interpret derivatives as local rates of change.","Use gradients to understand parameter updates.","Use distributions to represent uncertainty."]},
 "data-with-python":{focus:"NumPy arrays provide typed, vectorised numerical operations. Pandas DataFrames add labelled columns and operations for filtering, grouping, joining and missing-value handling. A pipeline must preserve row meaning and avoid leakage.",example:"Load transactions, inspect dtypes and null counts, remove duplicate IDs, parse timestamps, aggregate spend by customer and join customer metadata. Fit imputation only on training data.",ideas:["Inspect shape, dtypes, nulls and duplicate keys first.","Use vectorised NumPy operations where appropriate.","Check row counts after filters and joins.","Validate join cardinality and key uniqueness.","Fit learned preprocessing on training data only."]},
 "statistics-visualization":{focus:"Descriptive statistics summarise observed data; probability models uncertainty; confidence intervals quantify estimation uncertainty under assumptions; tests assess evidence against a null hypothesis.",example:"Compare two website conversion rates with sample sizes and confidence intervals. Check random assignment and avoid declaring a winner from repeated unplanned dashboard checks.",ideas:["Use median and quantiles for skewed distributions.","Inspect spread and shape, not only the mean.","Interpret intervals in the context of sampling assumptions.","Separate statistical from practical significance.","Choose charts and axis scales that do not distort comparisons."]},
 embeddings:{focus:"Embedding models map text, images or other items into vectors. Similarity measures compare their geometry, but the neighbourhood is useful only when the model captures distinctions relevant to the task.",example:"Embed support questions, retrieve nearest neighbours and label a small query-document set. Compare cosine similarity with a lexical baseline and inspect false neighbours.",ideas:["Know whether the model embeds tokens, sentences or passages.","Check dimensions, normalisation and model version.","Distinguish cosine similarity from Euclidean distance.","Evaluate neighbours with labelled examples.","Re-embed consistently when changing model versions."]},
 vectordb:{focus:"A vector record commonly contains an ID, vector and metadata. An index accelerates nearest-neighbour search by trading recall, memory, build time and latency; filters and lifecycle operations are production-critical.",example:"Index policy passages with source, version, page and access group. Apply user access filters during retrieval and compare approximate results with exact-search ground truth.",ideas:["Define vector dimensions and metadata schema.","Understand top-k and approximate-neighbour trade-offs.","Apply access filters during retrieval.","Design upsert, delete and re-index operations.","Benchmark recall, latency, memory and filter correctness."]},
 "semantic-search":{focus:"Semantic retrieval encodes queries and documents into vectors, retrieves candidates and may rerank them. Hybrid retrieval combines vector signals with lexical matching for exact names, codes and phrases.",example:"Search for 'reset a locked account' when the document says 'unlock user credentials'. Compare keyword-only, vector-only and hybrid results and judge the top ten.",ideas:["Compare lexical and semantic matching on paraphrases.","Treat retrieval as candidate generation, not proof of relevance.","Combine sparse and dense signals when exact terms matter.","Use reranking on a manageable candidate set.","Measure precision, recall and ranking quality."]},
 chunking:{focus:"Chunking defines what a retrieval system can find and pass to a model. Parsing, semantic boundaries, overlap and provenance metadata determine whether context and citations survive splitting.",example:"Split a policy PDF by headings and paragraphs while preserving policy ID, section, page and version. Compare fixed-token chunks with section-aware chunks on questions involving exceptions.",ideas:["Parse structure before splitting plain text.","Preserve semantic units and heading context.","Use overlap only when it improves continuity.","Attach source, page, version and access metadata.","Evaluate retrieval using traceable source passages."]},
 rag:{focus:"A RAG pipeline parses and chunks documents, embeds and indexes them, retrieves and reranks candidates, assembles grounded context and generates an answer. Each stage has separate failure modes.",example:"For a policy assistant, retrieve only passages the employee may access, include policy version and section, require citations and test questions whose answers are absent.",ideas:["Separate ingestion, indexing, retrieval and generation.","Measure whether correct evidence appears in top-k.","Preserve document versions and permissions.","Require claims to be supported by retrieved passages.","Test missing evidence, conflicts and malicious document text."]},
 "ai-agents":{focus:"An agent loop observes context, chooses a tool, submits structured arguments, receives results and decides whether to continue. Application code must validate arguments, enforce permissions and bound execution.",example:"A support agent may read a booking and draft a change request, but must obtain confirmation before changing it and must never claim a tool succeeded without a result.",ideas:["Distinguish workflows from model-directed agent loops.","Define narrow tool schemas and validate arguments.","Enforce permissions in tool services, not prompts.","Make side effects idempotent and approval-gated.","Set budgets, timeouts and stop conditions."]},
 finetuning:{focus:"Fine-tuning adapts model parameters using task-specific examples. Compare it with prompting and RAG first; then curate data, preserve held-out tests and measure capability, regression, safety and cost.",example:"For consistent support-ticket classification, first test prompting and retrieval. If behaviour remains inadequate, curate labelled examples, remove sensitive data and compare a tuned model with the base model on held-out rare cases.",ideas:["Choose adaptation based on the failure being solved.","Curate examples for coverage, correctness and rights.","Keep a held-out test set untouched.","Compare adapted and base models with simpler baselines.","Monitor regressions, safety and drift."]}
};

const aiChapterContent = [
{explain:"Artificial intelligence is the broad field of building systems that perform tasks associated with human judgement, perception or problem-solving. Start with the task, not the technology: identify the user, the decision or action to support, available information and a useful outcome. A solution may use rules, search, a statistical model, a language model or a combination. AI is not one product and does not guarantee human-like understanding.",bullets:["Describe the user, task and desired outcome before choosing a technique.","Separate inputs, processing, outputs and the people affected.","Define success using an observable measure.","Check whether a simple rule or conventional program is sufficient.","Decide who handles uncertainty, errors and appeals."],example:"A university receives thousands of course enquiries. Rules can route messages with clear categories; a classifier can suggest a category for ambiguous messages; staff handle sensitive or unclear cases. The outcome is faster routing without losing important enquiries.",task:"Choose a real problem such as sorting support emails. Write a problem statement, name the user, list available information, define one measurable success metric and identify one case that must go to a human.",hint:"Do not write 'use AI' as the problem. Describe the delay, error or decision the person experiences."},
{explain:"AI has developed through overlapping approaches. Early symbolic systems represented knowledge with explicit rules and logic. Statistical machine learning made it practical to learn patterns from examples. Deep learning uses multi-layer neural networks to learn complex representations. Foundation models are trained broadly and adapted to many tasks. These approaches have not simply replaced one another: rules, search, statistics and neural models remain useful for different problems.",bullets:["Symbolic systems represent knowledge with rules, facts and logic.","Machine learning estimates patterns from data.","Deep learning learns layered representations with neural networks.","Foundation models are trained broadly and adapted to downstream tasks.","Progress depends on data, algorithms, compute and evaluation — newer is not always better."],example:"A chess program may combine search and hand-designed evaluation; a spam filter may learn from labelled messages; a speech recogniser may use deep neural networks. Each approach addresses a different technical challenge.",task:"Create a five-row timeline covering symbolic AI, statistical machine learning, deep learning, foundation models and multimodal AI. For each, note the main idea, an enabling development and one application.",hint:"Focus on how systems represent knowledge or learn patterns, not just dates or product names."},
{explain:"Artificial intelligence is the umbrella field. Machine learning is an approach within AI in which systems learn patterns from data. Deep learning is a family of machine-learning methods based on multi-layer neural networks. Generative AI describes systems designed to produce content, often using deep-learning models. These categories overlap: a generative language model is typically a deep-learning model trained with machine-learning methods, and therefore belongs within the wider AI field.",bullets:["AI is the broad field of intelligent task performance.","Machine learning learns patterns or mappings from examples or experience.","Deep learning uses neural networks with multiple learned layers.","Generative AI focuses on producing text, images, audio, code and other content.","These terms describe related levels and capabilities, not mutually exclusive choices."],example:"A photo app that detects cats is an AI system. If it learned from labelled cat and non-cat photos, it uses machine learning. If it uses a multi-layer neural network, it uses deep learning. A tool that creates a new cat illustration from a prompt is generative AI.",task:"Classify four features: a fixed invoice rule, a model trained to predict late payments, a neural network that recognises objects and a tool that generates images from text. Explain how the categories relate.",hint:"A fixed rule can be part of an AI-enabled workflow without being machine learning."},
{explain:"Rule-based systems execute explicit conditions written by people. They are predictable when rules are complete, but become difficult to maintain as exceptions multiply. Data-driven systems infer patterns from examples and can handle variation, but their behaviour depends on training data and can be uncertain. Production systems often combine both: a model proposes or scores an outcome, while deterministic rules enforce policy, limits and permissions.",bullets:["Rules are explicit and auditable, but only cover anticipated conditions.","Learned models generalise from examples but can be uncertain or biased.","Use deterministic checks for hard constraints such as permissions and required fields.","Use learned models when patterns are difficult to express as rules and suitable data exists.","Define clearly which component has authority in a hybrid system."],example:"For an insurance claim, rules verify required fields and policy status. A model prioritises unusual claims for review. A human investigator makes the final decision on high-impact or suspicious cases.",task:"Design a hybrid workflow for potentially fraudulent expense claims. List two fixed-rule checks, one pattern a model might detect and the point where a human must review the case.",hint:"A model's risk score is a signal for review, not proof of fraud."},
{explain:"Data is recorded information used by a system. A feature is an input variable describing an example, such as transaction amount or account age. A label is the target outcome supplied during supervised training, such as whether a transaction was later confirmed as fraudulent. A representation is the form in which information is encoded for processing: numbers, categories, tokens, images or vectors. The meaning, timing and quality of fields matter as much as the algorithm.",bullets:["An observation is one example or record in a dataset.","A feature is an input available when the system makes a prediction.","A label is the outcome a supervised model is trained to predict.","A representation encodes raw information in a form an algorithm can process.","Check missing values, inconsistent units, duplicates, sensitive data and future-information leakage."],example:"For a delivery-time model, one row represents one shipment. Distance, parcel weight and dispatch hour are candidate features. Actual delivery duration is the label. A field recording 'late delivery confirmed' after delivery would leak future information.",task:"Design a dataset for predicting whether a help-desk ticket will breach its response-time target. List five candidate features, the label, when each feature becomes available and one field to exclude because it is only known later.",hint:"Ask of every feature: would the team know this value at the exact moment the prediction is made?"},
{explain:"Search explores possible states or documents to find a goal or relevant result. Planning selects a sequence of actions that moves a system from its current state to a desired state while respecting constraints. Search algorithms examine alternatives; planners reason about action preconditions and effects. These methods suit problems that can be represented explicitly, such as routes, schedules, puzzles and task sequences.",bullets:["Represent the current situation as a state and the desired result as a goal.","Define actions, preconditions and effects.","Breadth-first search explores by depth; uniform-cost search accounts for path cost.","Heuristic search uses an estimate to guide exploration.","Validate a plan against constraints and changing conditions."],example:"A delivery planner represents locations as nodes and roads as weighted edges. It searches for a low-cost route, then replans if a road closes. A scheduler searches for assignments that satisfy staff availability and time constraints.",task:"Draw a route graph with at least five locations and weighted connections. Choose a start and destination, calculate two route costs and explain which route a lowest-cost search selects. Add a closed-road constraint.",hint:"Add the edge costs along each complete route. Do not choose only by number of stops."},
{explain:"Perception systems turn signals from the physical world into machine-readable information. Computer vision processes images or video; speech systems process audio; sensor systems interpret measurements such as temperature, motion or location. A pipeline may include capture, preprocessing, representation extraction, inference and a decision. Performance depends on sensor quality, lighting, noise and whether real conditions match evaluation data.",bullets:["Images, audio and sensor readings have different data and noise characteristics.","Preprocessing may resize images, normalise audio or filter sensor noise.","Detection locates objects; classification assigns labels; segmentation labels pixels or regions.","Speech recognition converts audio into text; speaker recognition is a different task.","Test realistic conditions such as poor lighting, accents, background noise and sensor failures."],example:"A factory camera checks whether a safety helmet is present. It must handle shadows, different helmet colours, occlusion and camera angles. A low-confidence detection should trigger a safe review rather than silently approve an unsafe condition.",task:"Choose a perception task: helmet detection, noisy voice transcription or machine-vibration monitoring. Specify the input sensor, output, two noise sources, an evaluation measure and a safe response when confidence is low.",hint:"Choose metrics that match the task: object localisation and classification, transcription error, or anomaly false-alarm rates."},
{explain:"Language systems process or generate human language. Tasks include classifying text, extracting entities, translating, summarising, answering questions and generating dialogue. Earlier approaches used linguistic rules or statistical methods; modern systems commonly use neural networks and large language models. Language is ambiguous and context-dependent, so a fluent response is not necessarily correct. Evaluation must check meaning, factual support and harmful failure modes.",bullets:["Text classification assigns categories such as support intent.","Information extraction identifies structured fields such as dates or policy numbers.","Translation and summarisation should preserve the source meaning.","Question answering must distinguish supported answers from missing information.","Verify important claims against trusted sources; fluency is not proof."],example:"A customer writes, 'My card was charged twice.' An assistant may classify a billing dispute, extract an order reference and retrieve the approved process. It must not invent a refund status if no transaction record is available.",task:"Write three support messages: a clear request, an ambiguous request and one containing sensitive information. For each, specify expected intent, fields to extract, required source and whether the system should answer or escalate.",hint:"Account-specific facts must come from an authorised system, not be inferred from message wording."},
{explain:"Recommendation systems estimate which items may be useful to a person. Prediction systems estimate an outcome such as demand, delivery time or failure risk. Automation uses software to carry out a defined action and may rely on rules, predictions or generated content. A recommendation is usually advisory; an automated action can directly affect a user or process. Higher-impact actions require stronger validation and oversight.",bullets:["Prediction estimates an unknown or future value from available information.","Recommendation ranks options for a user or context.","Automation executes a workflow step under defined conditions.","Measure outcomes such as relevance, completion time, error rate and user impact.","Require approval or additional checks before consequential or irreversible actions."],example:"An online store predicts which products may interest a customer and ranks them. A warehouse automatically reorders stock when a threshold is crossed. These are different tasks and need different success measures.",task:"Compare a movie recommendation feature, a demand forecast and an automatic low-stock reorder. For each, state its input, output, affected person, suitable metric and whether a person should approve the action.",hint:"Click-through rate alone does not prove that a recommendation is useful or fair."},
{explain:"Evaluation asks whether a system performs its intended task reliably for the people and conditions that matter. Define a baseline, representative test cases and metrics that reflect the cost of errors. Average performance can hide rare failures or unequal outcomes. Evaluation should include correctness, robustness, latency and user outcomes. Monitor after release because data and behaviour change.",bullets:["Define success and failure before examining results.","Compare with a simple baseline or current human workflow.","Use task-appropriate metrics and inspect false positives and false negatives.","Test representative, edge, out-of-distribution and subgroup cases.","Monitor live performance, feedback, drift and incidents after deployment."],example:"A ticket-routing model achieves 92% accuracy but misroutes most urgent safety incidents. Overall accuracy hides the critical failure. A stronger evaluation measures urgent-ticket recall, routing delay and error rates by category.",task:"Create an evaluation plan for an AI complaint-routing system. Define a baseline, two metrics, three test groups including a high-impact case, a release threshold and one post-launch monitoring signal.",hint:"Explain why each metric matters. Missing an urgent case may be much costlier than sending an ordinary case to manual review."},
{explain:"AI systems can create or amplify risks through biased data, privacy violations, insecure integrations, unreliable outputs and unclear accountability. Responsible design starts before deployment: minimise data collection, check permissions, test performance across relevant groups, communicate limitations and provide human review. Safety belongs in requirements, architecture, testing and operations — not only in a disclaimer.",bullets:["Collect only data needed for a legitimate, defined purpose.","Check data rights, lawful basis, retention and access controls.","Test unequal error rates and harmful outcomes across relevant groups.","Protect against prompt injection, data leakage, insecure tools and misuse.","Assign accountable owners, escalation and appeal routes, and incident monitoring."],example:"A recruitment-screening tool ranks applications. Historical hiring data may reflect discrimination. The team must examine provenance, measure outcomes across groups, avoid inappropriate proxy attributes, keep humans accountable and provide a review route.",task:"Perform a risk review for an AI applicant-shortlisting tool. Identify affected people, sensitive data, three possible harms, preventive controls, a human oversight point and how a person can challenge an incorrect result.",hint:"Consider proxy variables such as postcode or employment gaps. A reviewer needs real authority and time to disagree with the system."},
{explain:"A practical AI solution begins with a clear problem and a justified design. Map the user journey, inputs, processing components, outputs, safeguards and feedback. Choose rules, search, prediction, generation or a hybrid based on the task and evidence. Define acceptance criteria, evaluate against a baseline and document limitations. The best solution is the simplest approach that safely meets the need.",bullets:["State the user problem and measurable outcome.","Choose the simplest suitable method and justify alternatives.","Map data sources, components, interfaces, decisions and human checkpoints.","Define evaluation cases, success thresholds and failure handling.","Document privacy, security, fairness, operational ownership and limitations."],example:"A campus help-desk assistant answers common questions from approved university documents, retrieves the source passage, asks for clarification when needed and transfers personal or urgent cases to staff. A deterministic baseline handles opening hours and contact details.",task:"Create a one-page solution brief for a campus help-desk assistant. Include the problem, scope, users, data sources, proposed architecture, simpler baseline, evaluation metrics, three failure cases, privacy/security controls and human escalation.",hint:"Make each requirement testable. State how you will demonstrate it works and what the system does when it cannot meet the requirement."}
];

const pythonChapterContent = [
{explain:"Python is an interpreted, general-purpose language widely used in automation, data analysis and AI tooling. A Python file is executed by an interpreter; a notebook runs code in individual cells and keeps a live kernel state. Install a supported Python version, verify which interpreter your terminal uses and keep project files in a dedicated folder. Run small examples before adding libraries so that errors are easier to isolate.",bullets:["The Python interpreter executes source code.","A script runs as a file; a notebook runs code in cells with retained kernel state.","The working directory determines how relative file paths are resolved.","Use the same interpreter for installing packages and running your project.","Restart a notebook kernel to check that code works from a clean state."],example:"Create hello.py with print('Hello, AI Simplified!'). Run it from the terminal using python hello.py. If the command is not recognised, check the Python installation and PATH rather than changing the program.",code:"print('Hello, AI Simplified!')\nprint(2 + 3)",output:"Hello, AI Simplified!\n5",task:"Create and run a Python script that prints your name, the Python version using import sys; print(sys.version), and the result of 17 * 6. Save the file and run it again from a terminal.",hint:"The terminal command should point to the same Python interpreter you will use to install project packages."},
{explain:"A variable is a name bound to an object. Python values have types: int for whole numbers, float for decimal numbers, str for text, bool for True or False, and None for the absence of a value. Python is dynamically typed, so a name can later refer to an object of another type. Convert deliberately when reading text input or combining values; do not assume a numeric-looking string is already a number.",bullets:["Use type(value) to inspect an object's type.","int, float, str and bool represent common scalar values.","None is distinct from zero, an empty string and False.","Use int() or float() for numeric conversion and validate user input.","Use descriptive variable names and avoid shadowing built-in names such as list or sum."],example:"The expression '42' is a string, while int('42') is an integer. Adding 8 to the integer gives 50; concatenating the string with another string produces text, not arithmetic.",code:"age_text = '34'\nage = int(age_text)\nnext_year = age + 1\nprint(type(age_text).__name__)\nprint(next_year)",output:"str\n35",task:"Create variables for a course title, number of chapters, completion percentage and whether the course is published. Print each value and its type. Convert a numeric string to an integer and calculate how many chapters remain if 3 of 12 are complete.",hint:"A string containing digits is still text until you convert it. Use int() for whole-number counts and float() for decimal measurements."},
{explain:"Strings are immutable sequences of Unicode characters. Use quotes to create them, f-strings to insert values into readable messages and string methods such as strip(), lower(), split() and replace() to clean or transform text. input() always returns a string, so validate and convert it before using it in calculations. Be careful with missing or blank input.",bullets:["Use f-strings for readable interpolation: f'Hello {name}'.","strip() removes surrounding whitespace; lower() normalises case.","split() separates text into a list using a delimiter or whitespace.","Strings are immutable; methods return new strings.","Validate user input before converting or processing it."],example:"A user enters '  Python for AI  '. strip() removes the extra spaces and lower() produces 'python for ai'. The original string is not changed.",code:"course = '  Python for AI  '\nclean = course.strip()\nprint(clean)\nprint(f'Welcome to {clean}!')\nprint(clean.lower())",output:"Python for AI\nWelcome to Python for AI!\npython for ai",task:"Ask the user for a course name and their study hours. Remove extra spaces from the course name, convert the hours to a number, and print a sentence stating how many hours they plan to study. Handle blank course names and invalid numeric input.",hint:"Use input().strip() for text. Put float(input(...)) inside a try block so invalid text does not crash the program."},
{explain:"Python collections organise related values. A list is ordered and mutable; a tuple is ordered and immutable; a set stores unique hashable values; a dictionary maps keys to values. Choose the structure based on how data will be accessed and changed. Dictionary keys should be stable and unique. Nested collections can represent records, but keep their structure consistent.",bullets:["Lists support indexing, slicing, append() and iteration.","Tuples are useful for fixed groups of values.","Sets remove duplicates and support membership tests.","Dictionaries map unique keys to values and support safe lookup with get().","Choose a collection based on ordering, uniqueness and mutation needs."],example:"A list of quiz scores can be appended to as learners submit work. A set of those scores gives the distinct values. A dictionary can map a learner ID to their score.",code:"scores = [80, 90, 80]\nunique_scores = set(scores)\nlearner = {'name': 'Asha', 'score': 90}\nprint(len(scores), len(unique_scores))\nprint(learner.get('score'))",output:"3 2\n90",task:"Create a list of five chapter names, a tuple containing a course code and level, a set of unique learner skills and a dictionary for one learner with name, completed_chapters and active. Print a selected item and update the dictionary after completing a chapter.",hint:"Use list indexing for a specific chapter, set() to remove duplicates and dictionary keys to access named learner fields."},
{explain:"Conditional logic chooses which code runs. Comparisons such as ==, !=, < and >= produce Boolean values. Combine conditions with and, or and not, and use if, elif and else to express mutually exclusive paths. Distinguish equality (==) from assignment (=). For multiple categories, order conditions carefully so that a broad condition does not capture cases meant for a narrower one.",bullets:["if runs a block when a condition is true.","elif checks another condition only when earlier conditions were false.","else handles remaining cases.","Use == for equality and = for assignment.","Validate boundaries explicitly, including zero, negative and maximum values."],example:"A score of 72 belongs in the 70–89 band. Check the highest band first, then the next band, to avoid assigning a score of 95 to a lower category.",code:"score = 72\nif score >= 90:\n    grade = 'A'\nelif score >= 70:\n    grade = 'B'\nelse:\n    grade = 'C'\nprint(grade)",output:"B",task:"Write a course-progress classifier: 0–39 is 'Getting started', 40–79 is 'In progress' and 80–100 is 'Nearly complete'. Reject values outside 0–100 and test the boundary values 0, 39, 40, 79, 80 and 100.",hint:"Test exact boundaries, not only typical values. Put the range check before assigning a progress label."},
{explain:"Loops repeat work. A for loop iterates over items in an iterable such as a list or range; a while loop repeats while a condition remains true. Use break to exit and continue to skip to the next iteration, but avoid unnecessary control-flow complexity. Track loop state clearly and ensure while loops can terminate. Prefer direct iteration over manually managing indexes when possible.",bullets:["for iterates through items in a collection or range.","range(stop) produces integer values from zero up to, but not including, stop.","while repeats while its condition remains true.","break exits a loop; continue skips the rest of the current iteration.","Accumulators and counters must be initialised before the loop."],example:"To total scores, start total at zero and add each score in a for loop. The final total is the sum of all values.",code:"scores = [70, 85, 90]\ntotal = 0\nfor score in scores:\n    total += score\nprint(total)\nprint(total / len(scores))",output:"245\n81.66666666666667",task:"Given a list of five quiz scores, calculate the total, average, highest score and number of scores at least 80. Then use a while loop to ask for a valid score between 0 and 100.",hint:"Initialise total and count before the loop. Consider what should happen if the list is empty before calculating an average."},
{explain:"Functions package a task behind a name and a defined interface. Parameters receive inputs; return sends a result back to the caller. Local variables exist inside the function. Use default parameters carefully, avoid mutable default values and keep functions focused. A function should usually return a value rather than print it, so that other code can reuse and test the result.",bullets:["Define a function with def and call it using parentheses.","Parameters describe required inputs; return provides the result.","A local variable is scoped to the function body.","Use docstrings to explain purpose, inputs and output where helpful.","Prefer small functions with one clear responsibility and predictable behaviour."],example:"A calculate_average function accepts a list of scores and returns the mean. The caller decides whether to print, store or compare that result.",code:"def calculate_average(scores):\n    if not scores:\n        return None\n    return sum(scores) / len(scores)\n\nprint(calculate_average([70, 85, 90]))\nprint(calculate_average([]))",output:"81.66666666666667\nNone",task:"Write three functions: validate_score(value), calculate_average(scores) and completion_status(completed, total). Test normal inputs, an empty list, zero total chapters and invalid scores. Return values rather than printing inside each function.",hint:"Keep validation separate from calculation. Decide what an invalid input should return or whether it should raise a clear ValueError."},
{explain:"A module is a Python file that can be imported. A package groups related modules. The standard library provides modules such as math, json, csv and pathlib; third-party packages are installed into an environment. A virtual environment isolates project dependencies so one project's package versions do not interfere with another. Record dependencies and use the same environment for installation and execution.",bullets:["import makes module functionality available to a program.","The standard library ships with Python; third-party packages must be installed.","A virtual environment isolates project dependencies.","Use python -m pip so pip belongs to the selected interpreter.","Keep dependency declarations reproducible and never commit secrets or environment folders."],example:"Create and activate a virtual environment, then install a library using python -m pip install package-name. Run the script with the interpreter from that environment.",code:"# Create an environment (run in the terminal)\npython -m venv .venv\n\n# Windows PowerShell activation\n.\\.venv\\Scripts\\Activate.ps1\n\n# macOS / Linux activation\nsource .venv/bin/activate\n\npython -m pip install --upgrade pip",output:"The terminal prompt should show the environment name, commonly (.venv).",task:"Create a folder for a small Python project, create a .venv environment, activate it and run python --version plus python -m pip --version. Explain how you know both commands use the environment. Do not upload your environment folder to GitHub.",hint:"If PowerShell blocks activation, use the official Python/PowerShell execution-policy guidance for your machine rather than downloading an unknown script."},
{explain:"Errors are part of programming. Syntax errors prevent code from parsing; exceptions occur while code runs; logic errors produce the wrong result without necessarily crashing. Read the traceback from the bottom to identify the exception and relevant line. Catch only exceptions you can handle meaningfully. Use assertions for internal assumptions and tests to check expected behaviour after changes.",bullets:["Syntax errors indicate invalid Python structure.","Exceptions such as ValueError, TypeError and FileNotFoundError occur during execution.","Tracebacks show the call path and the line where an exception surfaced.","Catch specific exceptions and provide a useful recovery path.","Test normal, boundary and invalid inputs; do not hide failures with broad except blocks."],example:"int('abc') raises ValueError. A user-facing program can catch that specific exception and ask for a valid number instead of terminating.",code:"def parse_score(text):\n    try:\n        score = int(text)\n    except ValueError:\n        return 'Enter a whole number'\n    if not 0 <= score <= 100:\n        return 'Score must be 0 to 100'\n    return score\n\nprint(parse_score('abc'))\nprint(parse_score('105'))\nprint(parse_score('85'))",output:"Enter a whole number\nScore must be 0 to 100\n85",task:"Intentionally create and debug three errors: a misspelled variable, an invalid number conversion and a file-not-found error. Record the exception type, the line involved, the root cause and the fix. Add a test for each corrected behaviour.",hint:"Do not just change code until the error disappears. Explain why the exception occurred and add a test that would catch it again."},
{explain:"Files let programs persist and exchange data. Use pathlib for paths, with open() and a context manager so files close reliably. CSV stores tabular records; JSON stores structured objects such as dictionaries and lists. Specify encoding, validate required fields and handle missing or malformed files. Treat external files as untrusted input and avoid overwriting source data accidentally.",bullets:["Use with open(...) to manage file lifetime safely.","Use encoding='utf-8' for predictable text handling.","csv.DictReader reads rows using column names.","json.load reads JSON from a file; json.dump writes JSON.","Validate schema, missing fields and file paths before processing."],example:"A CSV of quiz results can be read row by row with DictReader, converted into typed values and summarised into a JSON report. The source CSV should remain unchanged.",code:"import csv\nimport json\nfrom pathlib import Path\n\npath = Path('scores.csv')\nwith path.open(encoding='utf-8', newline='') as file:\n    rows = list(csv.DictReader(file))\nsummary = {'rows': len(rows)}\nPath('summary.json').write_text(\n    json.dumps(summary, indent=2), encoding='utf-8'\n)\nprint(summary)",output:"For a CSV with 3 data rows: {'rows': 3}\nThe program writes summary.json in the current folder.",task:"Create scores.csv with columns learner,course,score and at least four records. Read it with csv.DictReader, convert scores to integers, calculate the average and write a summary.json file. Handle a missing file and a malformed score.",hint:"CSV values arrive as strings. Convert and validate them before calculating. Use newline='' when opening a CSV file."},
{explain:"Readable Python is easier to maintain, review and test. Use descriptive names, consistent indentation, small functions, clear module boundaries and comments that explain why rather than repeat what the code says. Keep configuration separate from logic, avoid duplicated code and write a main entry point for scripts. Use version control and a clean environment to make work reproducible.",bullets:["Follow standard naming conventions and consistent four-space indentation.","Keep functions small and avoid duplicated logic.","Use docstrings for public functions and comments for non-obvious decisions.","Separate configuration, data access, processing and presentation where appropriate.","Add tests and a clear main entry point; keep secrets out of source control."],example:"Instead of one long script that reads a file, cleans values, calculates statistics and prints results, split it into read_scores(), summarise_scores() and main(). Each function can be tested independently.",code:"def summarise_scores(scores):\n    if not scores:\n        raise ValueError('scores cannot be empty')\n    return {\n        'count': len(scores),\n        'average': sum(scores) / len(scores),\n        'highest': max(scores),\n    }\n\ndef main():\n    result = summarise_scores([70, 85, 90])\n    print(result)\n\nif __name__ == '__main__':\n    main()",output:"{'count': 3, 'average': 81.66666666666667, 'highest': 90}",task:"Refactor one earlier exercise into three functions and a main() entry point. Add docstrings, validate inputs, write at least three tests and include a README explaining how to run the program in a clean virtual environment.",hint:"A useful test checks a normal case, a boundary case and an invalid case. Keep file access outside the calculation function so the calculation can be tested with simple lists."},
{explain:"The capstone combines core Python skills into a small, testable data-inspection tool. The program reads a CSV of learning activity, validates its columns and values, reports missing or duplicate records, calculates useful summaries and writes a JSON report. Separate file loading, validation, analysis and output so failures are localised and each step can be tested. The tool should never silently discard malformed records.",bullets:["Define a CSV schema and document required columns and types.","Separate parsing, validation, analysis and report writing into functions.","Report malformed rows with row numbers and reasons.","Calculate summary statistics only from validated records.","Write a reproducible JSON report and test missing, empty and malformed input files."],example:"A learning_activity.csv file may contain learner_id,course,completed_chapters,total_chapters. The program checks that counts are non-negative and completed_chapters does not exceed total_chapters, then calculates completion percentages and writes a course summary.",code:"from pathlib import Path\nimport csv, json\n\ndef inspect_csv(path):\n    required = {'learner_id', 'course', 'completed_chapters', 'total_chapters'}\n    with Path(path).open(encoding='utf-8', newline='') as file:\n        reader = csv.DictReader(file)\n        if not required.issubset(reader.fieldnames or []):\n            raise ValueError('Missing required columns')\n        rows = list(reader)\n    valid = []\n    errors = []\n    for line, row in enumerate(rows, start=2):\n        try:\n            done = int(row['completed_chapters'])\n            total = int(row['total_chapters'])\n            if done < 0 or total <= 0 or done > total:\n                raise ValueError('Invalid chapter counts')\n            valid.append({**row, 'completion_pct': round(done / total * 100, 1)})\n        except (ValueError, TypeError) as error:\n            errors.append({'line': line, 'reason': str(error)})\n    return {'valid_rows': len(valid), 'errors': errors, 'records': valid}\n\nreport = inspect_csv('learning_activity.csv')\nPath('report.json').write_text(json.dumps(report, indent=2), encoding='utf-8')\nprint(report['valid_rows'], 'valid records')",output:"With two valid rows and one invalid row, the report records 2 valid records and one line-specific validation error. Exact values depend on your CSV.",task:"Build the complete CSV inspection program. Submit your Python files, a sample CSV with at least eight records, generated JSON report, three automated tests and a README. Include duplicate IDs, missing values and invalid chapter counts in your test data. Explain what the report tells a learning-platform administrator.",hint:"Keep the original CSV unchanged. Make invalid rows visible in the report, and test the program with a missing file, an empty file, missing columns and invalid numeric values."}
];
const modules = Object.fromEntries(coreCourses.map(([id,title,level,chapters])=>{if(id==="ai")return [id,{outcome:"Explain core AI approaches, choose suitable methods for real problems, and evaluate limitations and risks.",modules:chapters.map((chapter,i)=>({title:chapter,...aiChapterContent[i]}))}];if(id==="python-basics")return [id,{outcome:"Write, debug, test and organise Python programs that inspect structured learning data and produce a validated report.",modules:chapters.map((chapter,i)=>({title:chapter,...pythonChapterContent[i]}))}];const g=teaching[id]||teaching.ai;return [id,{outcome:levels[level],modules:chapters.map((chapter,i)=>({title:chapter,explain:`${chapter} is important because ${g.focus}\n\nWork through this example: ${g.example} Identify the input, the transformation, the output and the evidence needed to trust the result. Then change one assumption — for example, introduce a missing value, an unseen category, a stale document or an ambiguous request — and predict what should happen.\n\nA practitioner should be able to explain why the chosen method is suitable, what simpler alternative was considered and where the method can fail. ${g.focus} Use the chapter exercise to turn this explanation into an observable artefact rather than relying on memorised terminology.`,bullets:g.ideas.map((idea,j)=>idea),example:g.example,task:`Practical lab — ${chapter}: ${g.example} Create a small worked artefact (table, diagram, notebook, test or design note). Include expected output, one negative or edge case, a validation check and a short interpretation of the result.`}))}]}));
const mlPractice=[
{q:"In a loan-default dataset, which field is the target label?",a:["Debt-to-income ratio","Whether the applicant defaulted within the defined period","Predicted probability","Row number"],correct:1,explain:"The label is the outcome the supervised model learns to predict. Debt-to-income may be a feature if available at prediction time."},
{q:"Why fit a scaler only on the training partition?",a:["To reduce test-set size","To prevent held-out information leaking into training","To increase feature count","To guarantee accuracy"],correct:1,explain:"Fit preprocessing on training data, then apply the learned transformation to validation and test data."},
{q:"A fraud class represents 1% of records. Which metric should be examined alongside precision?",a:["Recall","File size","Training time only","Number of columns"],correct:0,explain:"Recall measures how many actual fraud cases are found. Accuracy alone can hide poor detection of a rare class."},
{q:"A feature records whether a customer cancelled after the prediction date. What is the risk?",a:["Underfitting","Data leakage","Class balancing","Feature scaling"],correct:1,explain:"The feature contains future information unavailable at prediction time, inflating evaluation results."}
];

const aiPractice=[
{q:"A university wants to reduce time spent sorting enquiries. What should the team define first?",a:["Which AI model is most popular","The user problem, desired outcome and success measure","A chatbot personality","A large training dataset"],correct:1,explain:"Problem framing comes before model selection. Define the current workflow and measurable outcome."},
{q:"Which statement best describes AI, machine learning and deep learning?",a:["They are unrelated","Deep learning is broader than AI","Machine learning is within AI; deep learning is a family within machine learning","Generative AI and AI are synonyms"],correct:2,explain:"AI is the broad field; machine learning is one approach within AI; deep learning uses multi-layer neural networks."},
{q:"A system sends invoices over ₹1 lakh for approval using a fixed condition. Is this necessarily machine learning?",a:["Yes, because it makes a decision","No, it is a deterministic rule unless it learns patterns from data","Yes, because it runs on a computer","Only if the invoice is digital"],correct:1,explain:"A fixed condition is a rule-based program. It does not learn from examples."},
{q:"A fraud model uses a field populated only after investigation. What is the main risk?",a:["Data leakage","Underfitting","Low screen resolution","Model compression"],correct:0,explain:"The field is unavailable at prediction time and leaks future information into training or evaluation."},
{q:"For a supervised model predicting an SLA breach, what is the label?",a:["Ticket description","Customer region","Whether the ticket breached SLA within the defined period","Model confidence"],correct:2,explain:"The label is the historical outcome to predict. Other fields may be features if available at prediction time."},
{q:"Which problem is naturally represented as a search problem?",a:["Generating a poem","Finding the lowest-cost route through a road map","Summarising a meeting","Detecting sentiment"],correct:1,explain:"A route can be represented as states, connections and costs, allowing algorithms to compare paths."},
{q:"A helmet detector works in bright lab images but fails in dim factory lighting. What should be improved?",a:["Remove all confidence thresholds","Evaluate with representative real operating conditions","Change the logo","Add output labels without evidence"],correct:1,explain:"The deployment environment differs from evaluation data. Representative testing is needed to diagnose robustness."},
{q:"A language model gives a fluent refund status, but no transaction record was retrieved. What should the system do?",a:["Trust the answer","Invent a likely date","Say it cannot verify the status and retrieve an authorised record or escalate","Increase temperature"],correct:2,explain:"Fluency is not evidence. Account-specific claims require an authorised source."},
{q:"A film recommender produces a ranked list of titles. What task is it performing?",a:["Ranking items likely to be relevant","Guaranteeing the user's personality","Legal approval","Forecasting delivery time"],correct:0,explain:"Recommendation systems rank candidate items for a user or context."},
{q:"A complaint-routing model has 95% accuracy but misses most urgent safety complaints. What is the right conclusion?",a:["It is ready","The metric hides a critical failure; measure urgent-case recall and error costs","Delete the test set","Change the interface"],correct:1,explain:"Aggregate accuracy can hide rare, high-impact failures."},
{q:"A recruitment model performs worse for one applicant group. What is an appropriate next step?",a:["Ignore it if overall accuracy is high","Investigate data, proxy features and group-level errors, then apply accountable safeguards","Remove monitoring","Automate final decisions"],correct:1,explain:"Responsible AI requires investigating unequal outcomes and applying meaningful safeguards."},
{q:"Which design is strongest for a campus assistant that must not invent policy?",a:["Answer from model memory only","Use approved sources, show evidence, test unsupported questions and provide staff escalation","Access every student record","Optimise only for speed"],correct:1,explain:"Grounding, evaluation, permissions and escalation make the system more trustworthy."}
];

const pythonPractice=[
{q:"What does input() return in Python?",a:["An integer","A string","A Boolean","A list"],correct:1,explain:"input() returns text. Convert and validate it before numeric calculations."},
{q:"What is the value of int('42') + 8?",a:["'428'","50","42.8","TypeError"],correct:1,explain:"int('42') converts the string to integer 42; adding 8 produces 50."},
{q:"Which string method removes whitespace from both ends?",a:["split()","strip()","replace()","join()"],correct:1,explain:"strip() returns a new string without leading and trailing whitespace."},
{q:"Which collection is best suited to map a learner ID to a score?",a:["Dictionary","Tuple","Set","String"],correct:0,explain:"A dictionary maps unique keys such as learner IDs to values such as scores."},
{q:"Which operator tests equality?",a:["=","==",":=","!="],correct:1,explain:"== compares values. = assigns a value to a name."},
{q:"What does range(3) produce when iterated?",a:["1, 2, 3","0, 1, 2","0, 1, 2, 3","3 only"],correct:1,explain:"range(3) starts at zero and stops before three."},
{q:"Why should a reusable calculation function usually return a value?",a:["So callers can use and test the result","So it prints automatically","So it changes global variables","So it skips validation"],correct:0,explain:"Returning a value separates calculation from presentation and makes the function easier to test."},
{q:"Why use a virtual environment for a Python project?",a:["To isolate project dependencies","To encrypt Python code","To speed up every algorithm","To replace the interpreter"],correct:0,explain:"Virtual environments isolate installed packages and versions for each project."},
{q:"Which exception is raised by int('hello')?",a:["KeyError","ValueError","FileNotFoundError","IndexError"],correct:1,explain:"The text is a valid string but not a valid integer representation, so int() raises ValueError."},
{q:"Which is the safest common pattern for reading a text file?",a:["Leave it open globally","Use with open(..., encoding='utf-8') as file","Read it without checking the path","Catch every exception and ignore it"],correct:1,explain:"A with block closes the file reliably, including when an exception occurs."},
{q:"What should happen when a CSV score contains 'unknown'?",a:["Treat it as zero silently","Validate it and report the malformed row","Delete the whole source file","Assume it is 100"],correct:1,explain:"Malformed input should be visible and handled explicitly, not silently converted into a misleading value."},
{q:"Which capstone design is easiest to test?",a:["One long function that reads, cleans and prints everything","Separate functions for loading, validation, analysis and reporting","Hard-code the sample output","Skip error handling"],correct:1,explain:"Separating responsibilities lets each stage be tested independently and makes errors easier to locate."}
];
const practice=Object.fromEntries(coreCourses.map(([id,title])=>[id,id==="ai"?aiPractice:id==="python-basics"?pythonPractice:id==="ml"?mlPractice:[{q:`Which statement best describes the purpose of ${title}?`,a:["Apply a method without checking assumptions","Choose and validate a method against the task and evidence","Assume outputs are always correct","Skip baselines and edge cases"],correct:1,explain:"A useful solution connects the technique to the problem, tests assumptions and validates results."},{q:"Why establish a baseline?",a:["To compare whether the added method provides measurable value","To avoid evaluation","To hide failures","To increase complexity"],correct:0,explain:"A baseline gives a reference point for deciding whether the method improves the outcome."},{q:"What should happen when an edge-case test fails?",a:["Ignore it","Investigate the cause and define a safe response","Delete the test","Rely on average performance"],correct:1,explain:"Edge cases expose assumptions and operational risks that should inform acceptance criteria."},{q:"Which evidence best supports a release decision?",a:["A successful demo","Model confidence alone","Repeatable tests on representative held-out cases","An unverified explanation"],correct:2,explain:"Representative, repeatable evaluation is stronger than anecdotes or confidence scores."}]]));

export const coreCourseDeepDive=modules;
export const coreCourseChapterPractice=practice;
